using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.AI;
public static class InspectSchoolPlacement { public static object Run(){
var p="Assets/ThirdParty/SchoolExpansion/Characters/Casual_Male.fbx";var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(p));var an=g.GetComponent<Animation>();var clip=AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>().First(c=>c.name=="CharacterArmature|Idle");clip.SampleAnimation(g,0);var bounds=g.GetComponentsInChildren<Renderer>().Select(r=>new{r.name,center=r.bounds.center.ToString(),size=r.bounds.size.ToString()}).ToArray();UnityEngine.Object.DestroyImmediate(g);
var points=new System.Collections.Generic.List<object>();foreach(float z in new[]{-3.4f,-1.2f,-.1f,1.05f,2.25f,3.3f})foreach(float x in new[]{-2.35f,-1.1f,.15f,1.4f,2.65f}){NavMeshHit h;if(NavMesh.SamplePosition(new Vector3(x,0,z),out h,.25f,NavMesh.AllAreas)){var path=new NavMeshPath();bool ok=NavMesh.CalculatePath(h.position,new Vector3(15,0,0),NavMesh.AllAreas,path);points.Add(new{x,z,pos=h.position.ToString(),ok,status=path.status.ToString()});}}
return new{bounds,animation=an!=null,points,desks=GameObject.Find("Classroom - licensed source art").transform.Find("Desk").GetComponentsInChildren<Renderer>().Select(r=>new{r.name,center=r.bounds.center.ToString(),size=r.bounds.size.ToString()}).ToArray()};}}
